GLFWwindow* window = nullptr;
void create_geometry_node(std::shared_ptr<sg::Scene> scene, uint16_t num = 1);
uint32_t frame_id = 0;
void mainLoop() {
    while (!glfwWindowShouldClose(window)) {
        glfwPollEvents();
        
        static bool rendered = false;
        if (!rendered) {
            multi_pass_render->render_scene(scene);
        }
    }
    
    multi_pass_render->wait_idle();
    scene = nullptr;
    geo_node = nullptr;
    multi_pass_render = nullptr;
    
}

void create_geometry_node(std::shared_ptr<sg::Scene> scene, uint16_t num) {
    if (!geo_node) {
        // std::shared_ptr<sg::SingleLayerTexture> blue_tex = std::make_shared<sg::SingleLayerTexture>("images/test01.png");
        // geo_node = std::make_shared<sg::GeometryNode>("geo_node", blue_tex, 2);
        geo_node = std::make_shared<sg::GeometryNode>("geo_node", 2);
        // geo_node->is_renderable();
        // geo_node->reset();
        scene->add_node(geo_node);

        // auto rect_node = std::make_shared<sg::RectNode>("rect_node", 2, 1, blue_tex);5
        // scene->add_node(rect_node);
        scene->get_active_camera()->look_at(glm::vec3(0.0f, 0.0, 5.0f),
                                                 glm::vec3(0.0, 0, 0.0f),
                                                 glm::vec3(0.0f, 1.0f, 0.0f));
    }
    geo_node->reset();
    for (uint16_t i = 0; i < num; i++) {
        // glm::mat4 mat = glm::mat4_cast(glm::angleAxis(float(i * M_PI / num), glm::vec3(0, 0, 1)));
        geo_node->add_rect(glm::identity<glm::mat4>(), 3, 3, glm::vec4(1.0, 0.8, 0.6, 1.0));
        glm::mat4 mat = glm::mat4_cast(glm::angleAxis(float( M_PI / 8), glm::vec3(0, 0, 1)));
        geo_node->add_rect(mat, 3, 3, glm::vec4(0.0, 0.8, 0.6, 1.0));
    }
}

void create_complex_car_node(std::shared_ptr<sg::Scene> scene) {
    std::string node_path = "models/Cube/glTF/Cube.gltf";
    auto node = std::make_shared<sg::GltfNode>(node_path);
    node->get_component<sg::Transform>()->set_scale(glm::vec3(1.0f));
    node->rotate(1, 0, 0, 0.5);

    scene->add_node(node);

    scene->get_active_camera()->look_at(glm::vec3(0, 0, 10.0f),
                                             glm::vec3(0, 0, 0.0f),
                                             glm::vec3(0.0f, 1.0f, 0.0f));

}

void create_animation_node(std::shared_ptr<sg::Scene> scene) {
    std::string node_path = "models/26walk/26walk.gltf";
    auto node = std::make_shared<sg::GltfNode>(node_path);

    // node->get_component<sg::Transform>()->set_scale(glm::vec3(40.0, 40.0, 40.0));
    node->get_component<sg::Transform>()->set_translation(glm::vec3(5, -0.0, 0.0));

    auto node1 = std::make_shared<sg::Node>(*(node));
    // node1->get_component<sg::Transform>()->set_scale(glm::vec3(50.0, 50.0, 25.0));
    node1->get_component<sg::Transform>()->set_translation(glm::vec3(-5, 0.0, 0.0));

    auto animations1 = node->get_animation("test_animation1");

    for (auto animation : animations1) {
        animation->play(15);
        animation->set_is_looped(true);
    }
    scene->add_node(node);


    auto animations2 = node1->get_animation("test_animation1");

    for (auto animation : animations2) {
        animation->play(10);
        animation->set_is_looped(true);
    }
    scene->add_node(node1);

    scene->get_active_camera()->look_at(glm::vec3(0, 0, 10.0f),
                                             glm::vec3(0, 0, 0.0f),
                                             glm::vec3(0.0f, 1.0f, 0.0f));
}

